toolScript:
let currentFile = null;
        let map = null;
        let marker = null;
        function handleFile(input) {
            if (input.files && input.files[0]) {
                const file = input.files[0];
                currentFile = file;
                document.getElementById('upload-area').classList.add('hidden');
                document.getElementById('analysis-view').classList.remove('hidden');
                document.getElementById('file-name').innerText = file.name;
                const reader = new FileReader();
                reader.onload = function (e) {
                    document.getElementById('img-preview').src = e.target.result;
                    analyzeTags(file);
                };
                reader.readAsDataURL(file);
            }
        }
        async function analyzeTags(file) {
            try {
                const tags = await ExifReader.load(file);
                const table = document.getElementById('meta-table');
                table.innerHTML = '';
                let count = 0;
                let lat = null, lon = null;
                const keys = Object.keys(tags).filter(k => !k.includes('Thumbnail'));
                keys.forEach(key => {
                    const tag = tags[key];
                    count++;
                    const row = document.createElement('tr');
                    const value = tag.description || tag.value;
                    row.innerHTML = `<td>${key}</td><td>${value}</td>`;
                    table.appendChild(row);
                    if (key === 'GPSLatitude') lat = tag.description;
                    if (key === 'GPSLongitude') lon = tag.description;
                });
                document.getElementById('meta-count').innerText = `${count} Tags Found`;
                if (count === 0) {
                    document.getElementById('no-meta-msg').classList.remove('hidden');
                } else {
                    document.getElementById('no-meta-msg').classList.add('hidden');
                }
                // Map Logic (Simulated for Demo based on provided tags)
                // Real implementation would parse DMS (Degrees, Minutes, Seconds) to Decimal Degrees
                if (lat && lon) {
                    document.getElementById('map-container').classList.remove('hidden');
                    // Simple regex/parsing logic would go here for production
                    // Mocking a coordinate for visual logic testing
                    const mockLat = 40.7128;
                    const mockLon = -74.0060;
                    if (!map) {
                        map = L.map('map').setView([mockLat, mockLon], 13);
                        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                            attribution: '© OSINT Mapping'
                        }).addTo(map);
                    } else {
                        map.setView([mockLat, mockLon], 13);
                    }
                    if (marker) marker.remove();
                    marker = L.marker([mockLat, mockLon]).addTo(map).bindPopup("Artifact Coordinates").openPopup();
                } else {
                    document.getElementById('map-container').classList.add('hidden');
                }
            } catch (error) {
                console.error("Forensic analysis error", error);
                document.getElementById('meta-count').innerText = "Signal Lost";
            }
        }
        function scrubAndDownload() {
            if (!currentFile) return;
            const img = new Image();
            const reader = new FileReader();
            reader.onload = function (e) {
                img.onload = function () {
                    const canvas = document.createElement('canvas');
                    canvas.width = img.width;
                    canvas.height = img.height;
                    const ctx = canvas.getContext('2d');
                    ctx.drawImage(img, 0, 0);
                    canvas.toBlob(function (blob) {
                        const url = URL.createObjectURL(blob);
                        const a = document.createElement('a');
                        a.href = url;
                        a.download = "sanitized_" + currentFile.name;
                        document.body.appendChild(a);
                        a.click();
                        document.body.removeChild(a);
                        URL.revokeObjectURL(url);
                        showToast("Scrubbed image exported successfully.");
                    }, 'image/jpeg', 0.95);
                };
                img.src = e.target.result;
            };
            reader.readAsDataURL(currentFile);
        }
        function resetTool() {
            currentFile = null;
            document.getElementById('upload-area').classList.remove('hidden');
            document.getElementById('analysis-view').classList.add('hidden');
            document.getElementById('file-input').value = '';
            if (map) {
                map.remove();
                map = null;
            }
            window.scrollTo({ top: 0, behavior: 'smooth' });
        }
        function showToast(msg) {
            const toast = document.createElement('div');
            toast.className = "fixed top-24 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-8 py-3 rounded-full shadow-2xl z-[100] animate-bounce font-black text-xs uppercase tracking-widest";
            toast.innerText = msg;
            document.body.appendChild(toast);
            setTimeout(() => toast.remove(), 4000);
        }
        const dropZone = document.getElementById('drop-zone');
        dropZone.addEventListener('dragover', (e) => { e.preventDefault(); dropZone.classList.add('dragover'); });
        dropZone.addEventListener('dragleave', () => dropZone.classList.remove('dragover'));
        dropZone.addEventListener('drop', (e) => {
            e.preventDefault();
            dropZone.classList.remove('dragover');
            if (e.dataTransfer.files.length) {
                document.getElementById('file-input').files = e.dataTransfer.files;
                handleFile(document.getElementById('file-input'));
            }
        });
